from AlgorithmImports import *
import math


class TwoSlotStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, fillForward=False).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, fillForward=False).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, fillForward=False).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, fillForward=False).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, fillForward=False).Symbol

        self.required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.latest_spy_close = None
        self.latest_aapl_close = None

        self.spy_crossed_above = False
        self.spy_crossed_below = False

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_entry_pending = False
        self.strategy_a_exit_pending = False
        self.strategy_b_entry_pending = False
        self.strategy_b_exit_pending = False

    def OnData(self, data):
        all_bars_present = all(
            symbol in data.Bars for symbol in self.required_symbols
        )

        self._update_market_state(data)

        if self.IsWarmingUp:
            return

        if not all_bars_present:
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        self._evaluate_sells()
        self._evaluate_buys()

    def _update_market_state(self, data):
        self.spy_crossed_above = False
        self.spy_crossed_below = False

        if self.spy in data.Bars:
            spy_close = float(data.Bars[self.spy].Close)
            self.latest_spy_close = spy_close

            current_spy_sma = None
            if self.spy_sma.IsReady:
                current_spy_sma = float(self.spy_sma.Current.Value)

            if (
                current_spy_sma is not None
                and self.previous_spy_close is not None
                and self.previous_spy_sma is not None
            ):
                self.spy_crossed_above = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and spy_close > current_spy_sma
                )

                self.spy_crossed_below = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and spy_close < current_spy_sma
                )

            self.previous_spy_close = spy_close

            if current_spy_sma is not None:
                self.previous_spy_sma = current_spy_sma

        if self.aapl in data.Bars:
            aapl_close = float(data.Bars[self.aapl].Close)
            self.latest_aapl_close = aapl_close

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

    def _evaluate_sells(self):
        if (
            self.strategy_a_lot > 0
            and not self.strategy_a_entry_pending
            and not self.strategy_a_exit_pending
            and self.spy_crossed_below
        ):
            self.strategy_a_exit_pending = True
            self.MarketOrder(
                self.spy,
                -self.strategy_a_lot,
                tag="Strategy A Exit"
            )

        if (
            self.strategy_b_lot > 0
            and not self.strategy_b_entry_pending
            and not self.strategy_b_exit_pending
            and float(self.aapl_rsi.Current.Value) > 60.0
        ):
            self.strategy_b_exit_pending = True
            self.MarketOrder(
                self.aapl,
                -self.strategy_b_lot,
                tag="Strategy B Exit"
            )

    def _evaluate_buys(self):
        if (
            self.strategy_a_lot == 0
            and not self.strategy_a_entry_pending
            and not self.strategy_a_exit_pending
            and self.spy_crossed_above
            and self.latest_spy_close is not None
            and self.latest_spy_close > 0
        ):
            target_value = float(self.Portfolio.TotalPortfolioValue) * 0.40
            quantity = math.floor(target_value / self.latest_spy_close)

            if quantity > 0:
                self.strategy_a_entry_pending = True
                self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="Strategy A Entry"
                )

        if (
            self.strategy_b_lot == 0
            and not self.strategy_b_entry_pending
            and not self.strategy_b_exit_pending
            and self.aapl_red_streak >= 3
            and self.latest_aapl_close is not None
            and self.latest_aapl_close > 0
            and float(self.Portfolio.Cash) >= 20000.0
        ):
            quantity = math.floor(20000.0 / self.latest_aapl_close)

            if quantity > 0:
                self.strategy_b_entry_pending = True
                self.MarketOrder(
                    self.aapl,
                    quantity,
                    tag="Strategy B Entry"
                )

    def OnOrderEvent(self, orderEvent):
        fill_quantity = int(orderEvent.FillQuantity)
        terminal = orderEvent.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

        if orderEvent.Symbol == self.spy:
            if fill_quantity > 0:
                self.strategy_a_lot += fill_quantity
                if terminal:
                    self.strategy_a_entry_pending = False
            elif fill_quantity < 0:
                self.strategy_a_lot = max(
                    0,
                    self.strategy_a_lot + fill_quantity
                )
                if terminal:
                    self.strategy_a_exit_pending = False
            elif terminal:
                if self.strategy_a_exit_pending:
                    self.strategy_a_exit_pending = False
                elif self.strategy_a_entry_pending:
                    self.strategy_a_entry_pending = False

        elif orderEvent.Symbol == self.aapl:
            if fill_quantity > 0:
                self.strategy_b_lot += fill_quantity
                if terminal:
                    self.strategy_b_entry_pending = False
            elif fill_quantity < 0:
                self.strategy_b_lot = max(
                    0,
                    self.strategy_b_lot + fill_quantity
                )
                if terminal:
                    self.strategy_b_exit_pending = False
            elif terminal:
                if self.strategy_b_exit_pending:
                    self.strategy_b_exit_pending = False
                elif self.strategy_b_entry_pending:
                    self.strategy_b_entry_pending = False

