        self.spy_lot = 0
        self.aapl_lot = 0

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_close_samples = 0

        self.last_evaluated_time = None

        self.set_warm_up(200, Resolution.DAILY)

    def _actual_bar(self, bars, symbol):
        bar = bars.get(symbol)
        if bar is None:
            return None

        if bool(getattr(bar, "is_fill_forward", False)):
            return None
        if bool(getattr(bar, "IsFillForward", False)):
            return None

        return bar

    def _order_accepted(self, ticket):
        return (
            ticket is not None
            and ticket.status != OrderStatus.INVALID
            and ticket.status != OrderStatus.CANCELED
        )

    def _buy_spy(self, close):
        target_value = 0.40 * float(self.portfolio.total_portfolio_value)
        shares = int(target_value / float(close))

        if shares <= 0:
            return

        ticket = self.market_order(self.spy, shares)
        if self._order_accepted(ticket):
            self.spy_lot = shares

    def _sell_spy(self):
        if self.spy_lot <= 0:
            return

        ticket = self.market_order(self.spy, -self.spy_lot)
        if self._order_accepted(ticket):
            self.spy_lot = 0

    def _buy_aapl(self, close):
        if float(self.portfolio.cash) < 20000.0:
            return

        shares = int(20000.0 / float(close))
        if shares <= 0:
            return

        ticket = self.market_order(self.aapl, shares)
        if self._order_accepted(ticket):
            self.aapl_lot = shares

    def _sell_aapl(self):
        if self.aapl_lot <= 0:
            return

        ticket = self.market_order(self.aapl, -self.aapl_lot)
        if self._order_accepted(ticket):
            self.aapl_lot = 0

    def on_data(self, data):
        bars = {
            symbol: self._actual_bar(data.bars, symbol)
            for symbol in self.symbols
        }

        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma
        previous_aapl_close = self.previous_aapl_close
        previous_aapl_red_streak = self.aapl_red_streak

        spy_close = None
        spy_sma = None

        if bars[self.spy] is not None:
            spy_bar = bars[self.spy]
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)

            spy_close = spy_bar.close
            if self.spy_sma.is_ready:
                spy_sma = self.spy_sma.current.value

            self.previous_spy_close = spy_close
            self.previous_spy_sma = spy_sma

        aapl_close = None
        aapl_rsi = None

        if bars[self.aapl] is not None:
            aapl_bar = bars[self.aapl]
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

            aapl_close = aapl_bar.close
            if previous_aapl_close is not None:
                if aapl_close < previous_aapl_close:
                    self.aapl_red_streak = previous_aapl_red_streak + 1
                else:
                    self.aapl_red_streak = 0
            else:
                self.aapl_red_streak = 0

            self.aapl_close_samples += 1
            self.previous_aapl_close = aapl_close

            if self.aapl_rsi.is_ready:
                aapl_rsi = self.aapl_rsi.current.value

        if self.is_warming_up:
            return

        if any(bars[symbol] is None for symbol in self.symbols):
            return

        if not self.spy_sma.is_ready or not self.aapl_rsi.is_ready:
            return

        if self.aapl_close_samples < 4:
            return

        current_time = bars[self.spy].end_time
        if self.last_evaluated_time == current_time:
            return
        self.last_evaluated_time = current_time

        spy_crosses_above = (
            previous_spy_close is not None
            and previous_spy_sma is not None
            and spy_sma is not None
            and previous_spy_close <= previous_spy_sma
            and spy_close > spy_sma
        )

        spy_crosses_below = (
            previous_spy_close is not None
            and previous_spy_sma is not None
            and spy_sma is not None
            and previous_spy_close >= previous_spy_sma
            and spy_close < spy_sma
        )

        aapl_buy_reason = self.aapl_red_streak >= 3
        aapl_sell_reason = aapl_rsi > 60

        if self.spy_lot > 0 and spy_crosses_below:
            self._sell_spy()

        if self.aapl_lot > 0 and aapl_sell_reason:
            self._sell_aapl()

        if self.spy_lot == 0 and spy_crosses_above:
            self._buy_spy(spy_close)

        if self.aapl_lot == 0 and aapl_buy_reason:
            self._buy_aapl(aapl_close)

